package com.digitalbase.ticketing.model;import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import lombok.*;import org.hibernate.annotations.CreationTimestamp;import java.time.Instant;@Entity@Table(name = "ticket_attachments")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class TicketAttachment {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "ticket_id", nullable = false)    @JsonIgnore    private Ticket ticket;    @Column(name = "file_name", nullable = false)    private String fileName;    @Column(name = "file_url", nullable = false)    private String fileUrl;    @Column(name = "file_type")    private String fileType;    @CreationTimestamp    @Column(name = "uploaded_at", updatable = false)    private Instant uploadedAt;}